export interface FeatureEstimate {
  name: string;
  category: 'auth' | 'database' | 'ui' | 'integration' | 'realtime';
  estimatedHours: number;
  hourlyRateUSD: number;
}

export function calculateMVPBudget(features: FeatureEstimate[]) {
  const totalHours = features.reduce((acc, item) => acc + item.estimatedHours, 0);
  const totalCostUSD = features.reduce(
    (acc, item) => acc + item.estimatedHours * item.hourlyRateUSD,
    0
  );

  // Buffer 15% for integration edge-cases and validation testing
  const contingencyBufferUSD = Math.round(totalCostUSD * 0.15);

  return {
    totalHours,
    baseCostUSD: totalCostUSD,
    contingencyBufferUSD,
    finalEstimatedBudgetUSD: totalCostUSD + contingencyBufferUSD,
    estimatedDeliveryWeeks: Math.ceil(totalHours / 35), // Based on 35 focused hours/week
  };
}

// Example: Lean MVP Scope
const initialScope: FeatureEstimate[] = [
  { name: 'Email/Password + OAuth Auth', category: 'auth', estimatedHours: 12, hourlyRateUSD: 50 },
  { name: 'PostgreSQL Schema + Row Security', category: 'database', estimatedHours: 16, hourlyRateUSD: 50 },
  { name: 'Dashboard UI & Data Tables', category: 'ui', estimatedHours: 28, hourlyRateUSD: 50 },
  { name: 'Stripe Subscription Billing', category: 'integration', estimatedHours: 20, hourlyRateUSD: 50 },
  { name: 'Real-time Status Updates', category: 'realtime', estimatedHours: 24, hourlyRateUSD: 50 },
];

const budget = calculateMVPBudget(initialScope);
console.log(`Estimated Total: $${budget.finalEstimatedBudgetUSD} across ${budget.estimatedDeliveryWeeks} weeks.`);
